#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_pop_successful_shrink(void) {
    DArrayStack *stack = NULL;
    int success = 0;
    int popped_value = 0;

    // Create a stack with even capacity (e.g., 4) and fill it to capacity/2 + 1
    // After one pop, top will be exactly at (capacity/2) - 1, triggering shrink_array
    // Example: capacity = 4, initial top = 2 (3 elements), after pop top = 1
    // Condition: capacity % 2 == 0 (true), capacity >= 2 (true), top <= (capacity/2)-1 (1 <= 1 true)
    stack = create_stack(4);
    TEST_ASSERT_NOT_NULL(stack);

    // Push 3 elements (top will be 2)
    int push_result = push(stack, 10);
    TEST_ASSERT_EQUAL_INT(0, push_result);
    push_result = push(stack, 20);
    TEST_ASSERT_EQUAL_INT(1, push_result);
    push_result = push(stack, 30);
    TEST_ASSERT_EQUAL_INT(2, push_result);

    // Verify initial state
    TEST_ASSERT_EQUAL_INT(4, show_capacity(stack));
    TEST_ASSERT_EQUAL_INT(3, stack_size(stack));
    TEST_ASSERT_EQUAL_INT(2, stack->top);

    // Test pop - should trigger shrink_array
    popped_value = pop(stack, &success);
    // Verify stack pointer is still valid after potential reallocation
    TEST_ASSERT_NOT_NULL(stack);

    // Assertions
    TEST_ASSERT_EQUAL_INT(1, success);  // success should be set to 1
    TEST_ASSERT_EQUAL_INT(30, popped_value);  // Last pushed element
    TEST_ASSERT_EQUAL_INT(1, stack->top);  // top decremented from 2 to 1
    // The element at old top position should be zeroed (implementation detail)
    // shrink_array should have been called (we can't directly assert its effect,
    // but we can verify stack still works)
    TEST_ASSERT_EQUAL_INT(1, stack_size(stack));

    // Verify stack still contains remaining elements
    TEST_ASSERT_EQUAL_INT(1, stack_contains(stack, 10));
    TEST_ASSERT_EQUAL_INT(1, stack_contains(stack, 20));
    TEST_ASSERT_EQUAL_INT(0, stack_contains(stack, 30));

    // Cleanup
    free_stack(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_pop_successful_shrink);
    return UNITY_END();
}

